    if (hero && !hero->IsDead() && !CPlayerGui::Get().GetSubtitleRenderer().IsInCutscene()) {
        CTCHero* heroTC;
        if (hero->GetTC(TCI_HERO, &heroTC) && heroTC->GiveTutorialForCategory((ETutorialCategory)0x21, false))
