    CTCOwnedEntity* owned;
    if (ParentThing->GetTC(TCI_OWNED_ENTITY, &owned) && owned->GetPOwner())
        GetWorld().GetMessageEventManager().AddMessage(MESSAGE_EVENT_THEFT, 0x32, user.GetPos(), &user, owned->GetPOwner(), 0.0f, 0.0f, 0);
