    bool ok = m.lastExpr == 1 && m.SymbolsFiring[2] == 1 && m.quits == 0 && m.R == 255 && (m.tail - m.head) == 1;
    m.frame = 115; m.Update();           // t = 0.5 -> sin(pi/2) = 1
